import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Réutiliser et examiner les variables d’exécution","description":"","frontmatter":{"title":"Réutiliser et examiner les variables d’exécution","docId":"user.automations.variables","translationKey":"user.automations.variables","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"afcdc4049fccbd2bc17c1040a9f84efb749a8d6291212cfe8809c22728e5c0fb","translationRevision":"1aeb8d2a32819be9341a987deab1fdc5ede05fbc87e59b8645cf5561ca78f731","order":40},"headers":[],"relativePath":"fr/user/automations/variables.md","filePath":"fr/user/automations/variables.md","lastUpdated":1795731074000}`),s={name:`fr/user/automations/variables.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="reuse-and-review-runtime-variables" tabindex="-1">Réutiliser et examiner les variables d’exécution <a class="header-anchor" href="#reuse-and-review-runtime-variables" aria-label="Permalink to “Réutiliser et examiner les variables d’exécution”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objectif et prérequis”">​</a></h2><p>Modifier une valeur partagée une seule fois et la réutiliser dans plusieurs actions. Il faut <strong>Automations → Variables</strong> et un hôte prenant en charge les opérations de variables concernées. L’édition typée et les opérations Cloud avec examen apparaissent selon les capacités de l’hôte ; enregistrer localement ne nécessite aucun téléversement.</p><h2 id="save-a-local-value" tabindex="-1">Enregistrer une valeur locale <a class="header-anchor" href="#save-a-local-value" aria-label="Permalink to “Enregistrer une valeur locale”">​</a></h2><ol><li>Ajoutez une variable nommée <code>showLabel</code>. Les clés commencent par une lettre ou un trait de soulignement et peuvent contenir lettres, chiffres, points, traits de soulignement et traits d’union, jusqu’à <code>64</code> caractères. Évitez les doublons.</li><li>Lorsque l’édition typée est disponible, choisissez le texte et saisissez <code>Émission du soir</code>. Les autres types pris en charge sont nombre, booléen, liste et secret. Les listes utilisent un tableau JSON de chaînes, tel que <code>[&quot;rouge&quot;, &quot;bleu&quot;]</code>.</li><li>Sélectionnez <strong>Save</strong>. Un conflit de révision signifie que la collection enregistrée a changé ; rechargez-la et comparez votre modification prévue à celle-ci.</li><li>Utilisez la valeur enregistrée dans un champ d’action acceptant les modèles :</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{{ globals.showLabel }}: {{ event.user.uniqueId }}</span></span></code></pre></div><ol start="5"><li>Testez une action limitée au journal pour examiner le texte rendu. Modifiez <code>showLabel</code>, enregistrez à nouveau et lancez un nouveau test. Les définitions d’action existantes peuvent réutiliser la valeur actualisée sans réimporter de modèle.</li></ol><p>Les <code>params</code> du modèle sont substitués lors de son application ; les <code>globals</code> sont lues à l’exécution. Une clé d’exécution manquante produit un texte vide : vérifiez donc son orthographe avant de l’utiliser dans une destination ou un identifiant. Utilisez les suggestions de variables du champ pour choisir les chemins d’événement adaptés à son déclencheur.</p><p>Les conditions peuvent aussi publier des valeurs par correspondance. Lorsqu&#39;un filtre déclare un alias de capture, la valeur qui l&#39;a satisfait est disponible pendant le rendu des actions de l&#39;événement sous la forme <code>{{ match.&lt;alias&gt; }}</code> (ou <code>{{ match.&lt;position&gt; }}</code> sans alias). Par exemple, une condition « commence par » sur le commentaire avec l&#39;alias <code>prefix</code> permet à une action de journal d&#39;afficher <code>{{ match.prefix }}</code>. Les captures sont du texte brut borné, ne sont produites que par les filtres et alternatives qui ont réellement correspondu, et ne modifient pas les clés de délai.</p><p>Appuyez sur <strong>+</strong> à côté d&#39;un champ compatible avec les modèles pour ouvrir <strong>Insérer une variable</strong> : le chemin exact apparaît à droite et choisir une ligne ajoute <code>{{ chemin }}</code> au champ. Les captures de cet événement figurent aussi dans la liste, mais ne sont résolues que si leur condition a réellement correspondu. Déclarez un alias dans la section Conditions (le bouton <strong>Capturer</strong> du pied affiche les champs d&#39;alias) pour écrire <code>{{ match.&lt;alias&gt; }}</code> ; sinon, utilisez la position <code>{{ match.&lt;position&gt; }}</code>.</p><h2 id="review-cloud-changes-separately" tabindex="-1">Examiner séparément les changements Cloud <a class="header-anchor" href="#review-cloud-changes-separately" aria-label="Permalink to “Examiner séparément les changements Cloud”">​</a></h2><p>La commande <strong>Changes</strong> de Variables dispose d’opérations natives avec examen d’envoi, récupération, application/adoption et retrait lorsqu’elles sont prises en charge. Enregistrez d’abord les modifications locales, sélectionnez une comparaison, examinez son type et sa valeur, puis choisissez explicitement la direction voulue. Récupérer une proposition Cloud est distinct de son application locale. Retirer une valeur partagée est distinct de la suppression d’une ligne locale.</p><p>Les valeurs secrètes ou bloquées sont masquées dans les comparaisons et ne peuvent pas être envoyées par ce parcours avec examen. Ne transformez jamais un secret en texte ordinaire pour contourner ce blocage.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Résultat attendu, état et récupération <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to “Résultat attendu, état et récupération”">​</a></h2><p>Les variables locales et le partage avec examen conditionné aux capacités sont disponibles ; enregistrer localement ne téléverse jamais automatiquement. Les clés invalides, valeurs typées invalides et révisions obsolètes bloquent l’enregistrement. Corrigez le champ signalé ou rechargez avant de réessayer. Pour les erreurs de compte, consultez le <a href="./../cloud/account.html">compte Cloud</a> ; pour les comparaisons, consultez <a href="./../cloud/changes.html">Changes</a>.</p><p>Essayez interactivement avant de toucher à votre vraie configuration :</p>`,16),t(d,{scenario:`automation`,locale:`fr`,panel:`automation`,title:`Essayez l'espace des automatisations`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Opérations en ligne de commande <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Opérations en ligne de commande”">​</a></h2><p>Chaque opération de ce guide est aussi disponible depuis la CLI — hors ligne, scriptable et adaptée aux agents. Les lignes d&#39;usage sont la syntaxe du parseur et restent en anglais dans toutes les langues.</p><table tabindex="0"><thead><tr><th>Commande</th><th>Résumé</th></tr></thead><tbody><tr><td><code>tiktools globals list</code></td><td>lister toutes les clés globales</td></tr><tr><td><code>tiktools globals get &lt;key&gt;</code></td><td>lire une globale</td></tr><tr><td><code>tiktools globals set &lt;key&gt; &lt;value&gt;</code></td><td>écrire une globale</td></tr><tr><td><code>tiktools globals delete &lt;key&gt;</code></td><td>supprimer une globale <strong>destructif</strong></td></tr></tbody></table><p>Consultez la <a href="./../../developer/cli.html">référence complète des commandes</a> pour les conventions, la sortie JSON et les marqueurs d’opérations destructives.</p>`,4)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};